import{_ as e,o as t,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"GraphRAG","description":"讲清 GraphRAG 的图索引资产、构建机制、Local/Global/DRIFT 查询方式，以及更新、成本与回退边界。","frontmatter":{"title":"GraphRAG","description":"讲清 GraphRAG 的图索引资产、构建机制、Local/Global/DRIFT 查询方式，以及更新、成本与回退边界。","framework":"Microsoft GraphRAG / Framework-neutral","version":"Python 3.12 / GraphRAG current docs","verified_at":"2026-07-29","source":["https://microsoft.github.io/graphrag/index/overview/","https://microsoft.github.io/graphrag/query/overview/","https://arxiv.org/abs/2404.16130"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/knowledge/advanced-rag/graphrag.md","filePath":"py-agent/knowledge/advanced-rag/graphrag.md","lastUpdated":1785318762000}'),s={name:"py-agent/knowledge/advanced-rag/graphrag.md"};function l(p,a,i,h,o,d){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="graphrag" tabindex="-1">GraphRAG <a class="header-anchor" href="#graphrag" aria-label="Permalink to &quot;GraphRAG&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>GraphRAG 是一种用<strong>实体、关系、社区及其摘要</strong>组织文档知识，再按问题范围检索这些图资产与原始文本的 RAG 方法。它主要解决跨文档关系、多跳实体问题和全局主题归纳；它不是“向量库旁边加一个图数据库”，也不是所有知识库的默认升级。</p><p>本文以 Microsoft GraphRAG 的公开概念为主要参照，但重点解释可迁移的图索引与查询机制。具体 CLI 和配置随版本变化较快，应用应以当前官方文档为准。</p><h2 id="_1-什么时候需要图结构" tabindex="-1">1. 什么时候需要图结构 <a class="header-anchor" href="#_1-什么时候需要图结构" aria-label="Permalink to &quot;1. 什么时候需要图结构&quot;">​</a></h2><p>先确认基础或高级向量 RAG 的失败是否真的来自关系结构：</p><table tabindex="0"><thead><tr><th>问题</th><th>图结构可能有价值</th><th>更简单的首选方案</th></tr></thead><tbody><tr><td>“项目 A 与供应商 B 通过哪些人员相关？”</td><td>需要实体与多跳关系</td><td>不适合只靠独立 Chunk</td></tr><tr><td>“整个语料中的主要风险主题是什么？”</td><td>需要社区与全局摘要</td><td>层次摘要也应作为基线</td></tr><tr><td>“退款期限是多少？”</td><td>单一局部事实</td><td>普通混合检索</td></tr><tr><td>“错误码 E102 的含义”</td><td>精确字符串</td><td>词法或键查询</td></tr><tr><td>文档很少且关系简单</td><td>图构建收益有限</td><td>元数据过滤与 Rerank</td></tr></tbody></table><p>只有当关系型问题在真实查询中占有足够比例，并且基础方案持续失败，GraphRAG 的构建和运维成本才可能合理。</p><h2 id="_2-图索引由哪些资产组成" tabindex="-1">2. 图索引由哪些资产组成 <a class="header-anchor" href="#_2-图索引由哪些资产组成" aria-label="Permalink to &quot;2. 图索引由哪些资产组成&quot;">​</a></h2><p>GraphRAG 的检索对象不只是一张图。</p><h3 id="_2-1-文本单元" tabindex="-1">2.1 文本单元 <a class="header-anchor" href="#_2-1-文本单元" aria-label="Permalink to &quot;2.1 文本单元&quot;">​</a></h3><p>文本单元保留原始证据、来源和位置。图中的实体或关系必须能回到这些文本单元，否则回答无法提供可核查引用。</p><h3 id="_2-2-实体" tabindex="-1">2.2 实体 <a class="header-anchor" href="#_2-2-实体" aria-label="Permalink to &quot;2.2 实体&quot;">​</a></h3><p>实体表示人、组织、产品、地点或领域对象。实体记录通常包含规范化名称、类型、描述和来源引用。实体抽取是概率过程，同名异物、别名和实体边界错误必须通过消歧处理。</p><h3 id="_2-3-关系与声明" tabindex="-1">2.3 关系与声明 <a class="header-anchor" href="#_2-3-关系与声明" aria-label="Permalink to &quot;2.3 关系与声明&quot;">​</a></h3><p>关系表示实体之间由文本支持的连接；声明可以记录带状态、时间或极性的事实。边必须保存出处、方向、置信信息和适用时间。没有来源的模型推断不能与文档明确陈述混为一条边。</p><h3 id="_2-4-社区与社区报告" tabindex="-1">2.4 社区与社区报告 <a class="header-anchor" href="#_2-4-社区与社区报告" aria-label="Permalink to &quot;2.4 社区与社区报告&quot;">​</a></h3><p>社区检测把连接密集的实体划分为群组；社区报告对各层社区的主要实体、关系和主题进行摘要。它们为全局问题提供检索入口，但摘要是派生资产，不是新的原始事实源。</p><h3 id="_2-5-向量与词法表示" tabindex="-1">2.5 向量与词法表示 <a class="header-anchor" href="#_2-5-向量与词法表示" aria-label="Permalink to &quot;2.5 向量与词法表示&quot;">​</a></h3><p>实体描述、社区报告和文本单元仍可建立向量或词法索引。图结构负责关系导航，向量表示负责从自然语言问题定位入口，两者是互补关系。</p><h2 id="_3-图索引的构建机制" tabindex="-1">3. 图索引的构建机制 <a class="header-anchor" href="#_3-图索引的构建机制" aria-label="Permalink to &quot;3. 图索引的构建机制&quot;">​</a></h2><p>Microsoft GraphRAG 的标准索引流水线包括实体、关系与声明抽取，社区检测、多层社区摘要以及向量化。通用流程可以表示为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始文档</span></span>
<span class="line"><span>  -&gt; 规范化与文本切分</span></span>
<span class="line"><span>  -&gt; 实体、关系、声明抽取</span></span>
<span class="line"><span>  -&gt; 实体规范化与消歧</span></span>
<span class="line"><span>  -&gt; 构建带来源的图</span></span>
<span class="line"><span>  -&gt; 社区检测</span></span>
<span class="line"><span>  -&gt; 生成多层社区报告</span></span>
<span class="line"><span>  -&gt; 为文本、实体和报告建立检索表示</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_3-1-抽取不是事实确认" tabindex="-1">3.1 抽取不是事实确认 <a class="header-anchor" href="#_3-1-抽取不是事实确认" aria-label="Permalink to &quot;3.1 抽取不是事实确认&quot;">​</a></h3><p>LLM 抽取会漏实体、合并错实体或推断不存在的关系。抽取结果要经过 Schema 校验、来源对齐、重复合并和领域规则检查。高风险关系可要求人工确认。</p><h3 id="_3-2-消歧决定图的可用性" tabindex="-1">3.2 消歧决定图的可用性 <a class="header-anchor" href="#_3-2-消歧决定图的可用性" aria-label="Permalink to &quot;3.2 消歧决定图的可用性&quot;">​</a></h3><p>“苹果”是公司还是水果，“张伟”是否为同一个人，都会改变图拓扑。消歧可以结合别名表、实体类型、邻域、文档位置和稳定业务 ID；不要只按名称字符串合并。</p><h3 id="_3-3-派生资产具有依赖关系" tabindex="-1">3.3 派生资产具有依赖关系 <a class="header-anchor" href="#_3-3-派生资产具有依赖关系" aria-label="Permalink to &quot;3.3 派生资产具有依赖关系&quot;">​</a></h3><p>实体或关系变化会影响社区划分和社区摘要。更新系统必须记录 <code>source_version -&gt; graph_elements -&gt; communities -&gt; reports</code> 的依赖，才能确定哪些资产需要重建。</p><h2 id="_4-三种主要查询方式" tabindex="-1">4. 三种主要查询方式 <a class="header-anchor" href="#_4-三种主要查询方式" aria-label="Permalink to &quot;4. 三种主要查询方式&quot;">​</a></h2><p>GraphRAG 不是单一查询算法。问题范围决定读取哪些资产。</p><h3 id="_4-1-local-search-围绕具体实体展开" tabindex="-1">4.1 Local Search：围绕具体实体展开 <a class="header-anchor" href="#_4-1-local-search-围绕具体实体展开" aria-label="Permalink to &quot;4.1 Local Search：围绕具体实体展开&quot;">​</a></h3><p>Local Search 从问题相关实体出发，组合实体、关系、声明、关联文本和部分社区信息。它适合“某实体有什么属性”“两个实体如何关联”等局部问题。</p><p>典型流向：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题 -&gt; 实体入口 -&gt; 邻域扩展 -&gt; 关联文本 -&gt; 预算裁剪 -&gt; 回答</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>扩展深度必须受限。高度连接的枢纽实体可能迅速带来大量无关邻居。</p><h3 id="_4-2-global-search-在社区报告上归纳" tabindex="-1">4.2 Global Search：在社区报告上归纳 <a class="header-anchor" href="#_4-2-global-search-在社区报告上归纳" aria-label="Permalink to &quot;4.2 Global Search：在社区报告上归纳&quot;">​</a></h3><p>Global Search 面向“整个语料的主要主题、风险或趋势”这类全局问题。Microsoft GraphRAG 在社区报告上执行类似 Map-Reduce 的处理：各社区先生成局部结论，再汇总为全局答案。</p><p>它通常比 Local Search 更消耗模型调用和 Token，不适合精确局部事实。社区报告的粒度与覆盖决定全局答案是否遗漏长尾主题。</p><h3 id="_4-3-drift-search-从社区视角下钻" tabindex="-1">4.3 DRIFT Search：从社区视角下钻 <a class="header-anchor" href="#_4-3-drift-search-从社区视角下钻" aria-label="Permalink to &quot;4.3 DRIFT Search：从社区视角下钻&quot;">​</a></h3><p>DRIFT Search 以社区信息扩大 Local Search 的起点，再生成更具体的跟进问题并下钻事实。它适合既需要较广视角又需要局部证据的问题，但查询轮次和成本更高，必须限制深度、分支数与总预算。</p><p>若项目不需要这类探索式问题，Local/Global 两条路径已经足够，不应为了“完整”默认启用 DRIFT。</p><h2 id="_5-上下文构建与引用规则" tabindex="-1">5. 上下文构建与引用规则 <a class="header-anchor" href="#_5-上下文构建与引用规则" aria-label="Permalink to &quot;5. 上下文构建与引用规则&quot;">​</a></h2><p>进入模型的上下文应区分三类内容：</p><ol><li>原始文本证据：可作为最终事实引用。</li><li>抽取的实体与关系：必须带回支持它们的文本来源。</li><li>社区报告：适合导航和主题归纳，应标注为派生摘要。</li></ol><p>回答中的关键声明至少对应一条原始证据。若社区报告提出了主题，但原始文本支持不足，应将其作为待验证线索，而不是确定事实。</p><p>图中存在边不等于因果成立；“A 与 B 共现”也不等于“A 导致 B”。生成提示和评测都要保留关系类型、方向与证据文本。</p><h2 id="_6-更新、一致性与删除" tabindex="-1">6. 更新、一致性与删除 <a class="header-anchor" href="#_6-更新、一致性与删除" aria-label="Permalink to &quot;6. 更新、一致性与删除&quot;">​</a></h2><p>图更新比独立 Chunk 更新更复杂：</p><ul><li>新文档可能新增实体，也可能与现有实体合并。</li><li>删除文档后，某条边可能仍有其他来源支持，不能简单整边删除。</li><li>边变化可能改变社区成员和多层报告。</li><li>别名规则改变可能导致大范围实体重映射。</li></ul><p>推荐为每个图元素维护来源集合和派生版本。删除一个来源时先移除支持关系；只有来源集合为空时才删除元素。社区报告读取单一已发布版本，避免索引更新中途混读新旧图。</p><h2 id="_7-成本、安全与回退" tabindex="-1">7. 成本、安全与回退 <a class="header-anchor" href="#_7-成本、安全与回退" aria-label="Permalink to &quot;7. 成本、安全与回退&quot;">​</a></h2><h3 id="_7-1-成本" tabindex="-1">7.1 成本 <a class="header-anchor" href="#_7-1-成本" aria-label="Permalink to &quot;7.1 成本&quot;">​</a></h3><p>GraphRAG 的主要额外成本发生在实体/关系抽取、社区摘要、图存储和多阶段查询。记录每千文档的抽取调用、社区报告 Token、增量更新范围，以及 Local/Global 查询的 P95 延迟。</p><h3 id="_7-2-安全" tabindex="-1">7.2 安全 <a class="header-anchor" href="#_7-2-安全" aria-label="Permalink to &quot;7.2 安全&quot;">​</a></h3><p>图会暴露跨文档连接。即使单个文档可见，连接后的推断也可能泄露敏感关系。权限过滤应作用于文本、实体、边和社区报告；跨租户数据不应进入同一可查询社区。</p><h3 id="_7-3-回退" tabindex="-1">7.3 回退 <a class="header-anchor" href="#_7-3-回退" aria-label="Permalink to &quot;7.3 回退&quot;">​</a></h3><ul><li>图入口解析失败：回退到文本混合检索。</li><li>局部图证据不足：返回文本证据，不编造关系路径。</li><li>Global Search 超预算：降低社区层级或回退到层次摘要。</li><li>图版本构建失败：继续服务上一个完整发布版本。</li></ul><h2 id="_8-一条可观察的查询轨迹" tabindex="-1">8. 一条可观察的查询轨迹 <a class="header-anchor" href="#_8-一条可观察的查询轨迹" aria-label="Permalink to &quot;8. 一条可观察的查询轨迹&quot;">​</a></h2><p>假设问题是“供应商北辰与项目 Atlas 通过哪些人员建立联系？”：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 实体链接：北辰 -&gt; vendor:beichen，Atlas -&gt; project:atlas</span></span>
<span class="line"><span>2. Local Search：分别扩展一跳人员关系</span></span>
<span class="line"><span>3. 路径交集：找到 person:li 与两个实体均有带来源的边</span></span>
<span class="line"><span>4. 证据回读：读取支持两条边的原文片段</span></span>
<span class="line"><span>5. 权限过滤：移除用户不可见来源及其边</span></span>
<span class="line"><span>6. 生成回答：描述路径，并分别引用两条原文证据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>若只有“北辰—李”有证据，而“李—Atlas”只是模型推断，系统应报告证据链不完整。</p><h2 id="_9-评测-graphrag" tabindex="-1">9. 评测 GraphRAG <a class="header-anchor" href="#_9-评测-graphrag" aria-label="Permalink to &quot;9. 评测 GraphRAG&quot;">​</a></h2><p>基础 RAG 必须作为对照。评测至少分三层：</p><table tabindex="0"><thead><tr><th>层级</th><th>指标示例</th></tr></thead><tbody><tr><td>图构建</td><td>实体准确率、别名合并错误率、关系证据覆盖、孤立元素率</td></tr><tr><td>检索</td><td>路径 Recall、Local Evidence Recall、Global Theme Coverage</td></tr><tr><td>回答</td><td>事实正确性、关系方向正确率、引用支持率、全局主题覆盖</td></tr></tbody></table><p>还要测量索引成本、更新时间、查询延迟和权限泄漏。若图方案只提高少量全局问题，却显著拖慢占多数的局部事实查询，可以做问题路由：局部事实走基础 RAG，只有关系型和全局问题进入 GraphRAG。</p><p>GraphRAG 的核心价值是让关系和全局结构成为可检索资产。它的前提是图元素可追溯、可更新、可授权，并且真实问题确实需要这些结构。</p>`,67)])])}const u=e(s,[["render",l]]);export{b as __pageData,u as default};
